    if (a.blocks && b.blocks) for (let i = 0; i < 7; i++) { const x = txt(a.blocks[i]), y = txt(b.blocks[i]); if (x !== y) out.push('Cyrkulacja ' + DL[i] + ': ' + x + ' → ' + y); }
