    const X0 = 46, X1 = 590, Y0 = 26, Y1 = 150;
    const sx = (t) => X0 + (t - t0) / (t1 - t0) * (X1 - X0), sy = (v) => Y1 - (v - lo) / ((hi - lo) || 1) * (Y1 - Y0);
