    return '<span>Grzanie CWU w taniej strefie dotąd: <b>' + (all ? Math.round(cheap / all * 100) : 0) + ' %</b> czasu (' + Math.round(all / 60) + ' h pracy na CWU w ' + R.days + ' dni)</span>';
